import os
import torch


class Config:
    """
    Configuration class for Multi-Task ResNeXt-FPN with Multi-Scale Attention.
    Centralizes all hyperparameters, file paths, and model settings.
    """

    # =========================================================================
    # Directories and Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata paths generated by the provided metadata script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for checkpoints and cached data
    WORKING_DIR = "./working/idea_3"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Submission directory
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Configuration
    # =========================================================================
    IMG_SIZE = 1024
    # A100 40GB can handle batch size 8 for ResNeXt-101 at 1024x1024
    BATCH_SIZE = 4
    NUM_WORKERS = 4

    # =========================================================================
    # Model Configuration
    # =========================================================================
    MODEL_NAME = "resnext101_32x8d"

    # Box Classes: 0=Background, 1=Typical, 2=Indeterminate, 3=Atypical
    # Note: 'Negative' studies have no boxes.
    NUM_BOX_CLASSES = 4

    # Study Classes: Negative, Typical, Indeterminate, Atypical
    NUM_STUDY_CLASSES = 4

    # Faster R-CNN Head Settings (High capacity for dense scenes)
    RPN_PRE_NMS_TOP_N_TRAIN = 2000
    RPN_POST_NMS_TOP_N_TRAIN = 2000

    RPN_PRE_NMS_TOP_N_TEST = 6000
    RPN_POST_NMS_TOP_N_TEST = 3000  # Increased from default to capture subtle opacities

    BOX_DETECTIONS_PER_IMG = 200  # Increased max detections
    BOX_SCORE_THRESH = (
        0.05  # Threshold for filtering low confidence boxes during inference
    )
    BOX_NMS_THRESH = 0.5  # IoU threshold for NMS

    # =========================================================================
    # Training Configuration
    # =========================================================================
    NUM_EPOCHS = 12

    # Optimizer settings (SGD with Momentum)
    LEARNING_RATE = 0.01
    MOMENTUM = 0.9
    WEIGHT_DECAY = 0.0005

    # Scheduler settings
    # Decay LR after 50-60% of epochs (Epoch 7 of 12)
    LR_DECAY_STEP = 7
    LR_GAMMA = 0.1

    # Loss Weights
    # Lambda for the global auxiliary head
    GLOBAL_HEAD_LOSS_WEIGHT = 0.5

    # =========================================================================
    # Miscellaneous
    # =========================================================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debug flag to run on a subset of data
    DEBUG = False

    # Mappings
    STUDY_ID_TO_LABEL = {
        0: "Negative for Pneumonia",
        1: "Typical Appearance",
        2: "Indeterminate Appearance",
        3: "Atypical Appearance",
    }

    LABEL_TO_STUDY_ID = {v: k for k, v in STUDY_ID_TO_LABEL.items()}
